import XCTest
import Recall

final class ReminderServiceTests: XCTestCase {
    func testRequestPermissionIfNeeded() async throws {
        // This test assumes that the user has already granted permission.
        let service = ReminderService()
        let isAuthorized = try await service.requestPermissionIfNeeded()
        XCTAssertTrue(isAuthorized)
    }

    func testSetReminderEnabledTrue() async throws {
        let schedulerMock = ReminderScheduler()
        let service = ReminderService(scheduler: schedulerMock)

        let components = DateComponents(hour: 12, minute: 0)
        try await service.setReminder(enabled: true, atComponents: components, deckID: UUID())
        XCTAssertEqual(try schedulerMock.cancelPendingCalled, false)
    }

    func testSetReminderEnabledFalse() async throws {
        let schedulerMock = ReminderScheduler()
        let service = ReminderService(scheduler: schedulerMock)

        try await service.setReminder(enabled: false, atComponents: nil, deckID: UUID())
        XCTAssertEqual(try schedulerMock.cancelPendingCalled, true)
    }

    func testRefreshNotificationsDueCountZero() async throws {
        let schedulerMock = ReminderScheduler()
        let service = ReminderService(scheduler: schedulerMock)

        try await service.refreshNotifications(now: Date())
        XCTAssertEqual(try schedulerMock.cancelPendingCalled, true)
    }
}
```

### Explanation:
- **requestPermissionIfNeeded**: Tests if the permission request returns `true` assuming the user has already granted permission.
- **setReminderEnabledTrue**: Ensures that notifications are scheduled when enabled is `true`.
- **setReminderEnabledFalse**: Ensures that all pending notifications are cancelled when enabled is `false`.
- **refreshNotificationsDueCountZero**: Tests if notifications are cancelled when the due count is zero.

